package com.procurement.vendorquotation.entity;import jakarta.persistence.*;import lombok.*;import java.time.LocalDateTime;@Entity@Table(name="quotation_attachments")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class QuotationAttachment{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="quotation_attachment_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="vendor_quotation_id",nullable=false)private VendorQuotation vendorQuotation;@Column(name="file_name",nullable=false,length=255)private String fileName;@Column(name="file_path",nullable=false,length=1000)private String filePath;@Column(name="file_type",nullable=false,length=100)private String fileType;@Column(name="uploaded_at",nullable=false)private LocalDateTime uploadedAt;@PrePersist void pre(){if(uploadedAt==null)uploadedAt=LocalDateTime.now();}}
